{"path": "test/widget/currency_list_page_test.dart", "content": "import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('CurrencyListPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();

    final currencyItems = [
      CurrencyModel(
        id: '1',
        nominal: 1,
        name: 'Доллар США',
        symbol: 'USD',
        value: 78.4181,
        previousValue: 78.5,
      ),
      CurrencyModel(
        id: '2',
        nominal: 1,
        name: 'Евро',
        symbol: 'EUR',
        value: 92.7440,
        previousValue: 92.2,
      ),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display all currency items when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('USD'), findsOneWidget);
      expect(find.text('EUR'), findsOneWidget);
      expect(find.text('JPY'), findsNothing);
      expect(find.byType(CurrencyCard), findsNWidgets(currencyItems.length));
    });

    testWidgets('should navigate to detail page when currency card is tapped', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should hide "show more" button when there are no next pages', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Показать ещё'), findsNothing);
    });

    testWidgets('should show "show more" button when next pages exist', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: true));

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Показать ещё'), findsOneWidget);
    });

    testWidgets('should reload currency list with USD base when focus is lost', (WidgetTester tester) async {
      final FocusNode searchFocusNode = FocusNode();
      addTearDown(searchFocusNode.dispose);

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      // Фокус внутри экрана — обновления не происходит.
      searchFocusNode.requestFocus();
      await tester.pumpAndSettle();
      verifyNever(mockCurrencyRepository.fetchRates(any));

      // Экран потерял фокус (например, открыт другой экран) — список обновляется свежим запросом.
      searchFocusNode.unfocus();
      await tester.pumpAndSettle();

      final VerificationResult result = verify(mockCurrencyRepository.fetchRates(captureAny));
      expect(result.callCount, 1);

      final CurrencyPageRequest request = result.captured.single as CurrencyPageRequest;
      expect(request.base, 'USD');
      expect(request.page, 0);
    });
  });
}
"}

